using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Net;using System.Net.Http;using System.Reflection;using System.Security.Cryptography;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Web.Script.Serialization;using System.Drawing;using System.Windows.Forms;using Org.BouncyCastle.Crypto.Parameters;using Org.BouncyCastle.Crypto.Signers;
namespace Veyra.Setup {
 internal sealed class TestProgress:IProgress<ProgressInfo>{public Action<ProgressInfo> Changed=delegate{};public void Report(ProgressInfo value){Changed(value);}}
 internal sealed class TestIntegration:IIntegration{public bool Fail,Restored,Removed;public void Apply(Layout layout,Options options,string version){if(Fail)throw new IOException("Simulated shortcut failure");}public void Rollback(){Restored=true;}public void Remove(Layout layout){Removed=true;}}
 internal sealed class FakeHttp:HttpMessageHandler{
  public byte[] Zip;public string Envelope;public Uri Redirect;public int Calls;
  protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){token.ThrowIfCancellationRequested();Calls++;var r=new HttpResponseMessage(HttpStatusCode.OK);if(Redirect!=null){r.StatusCode=HttpStatusCode.Redirect;r.Headers.Location=Redirect;}else r.Content=request.RequestUri.AbsoluteUri==Manifest.Feed?new ByteArrayContent(Encoding.UTF8.GetBytes(Envelope)):new ByteArrayContent(Zip);return Task.FromResult(r);}
 }
 internal static class Tests {
  static readonly JavaScriptSerializer Json=new JavaScriptSerializer();static Ed25519PrivateKeyParameters key;static byte[] pub;static string root;static int count;
  static void Check(bool condition,string text){if(!condition)throw new Exception(text);count++;}
  static byte[] Bundle(string content="verified",string extra=null){using(var memory=new MemoryStream()){using(var zip=new ZipArchive(memory,ZipArchiveMode.Create,true)){foreach(string name in new[]{"Veyra.exe","resources/app.asar","icudtl.dat","LICENSE"}){var entry=zip.CreateEntry("Veyra-win32-x64/"+name);using(var stream=entry.Open()){byte[] bytes=Encoding.UTF8.GetBytes(content);stream.Write(bytes,0,bytes.Length);}}if(extra!=null){var entry=zip.CreateEntry(extra);using(var stream=entry.Open()){stream.WriteByte(1);}}}return memory.ToArray();}}
  static string Envelope(byte[] zip,string version="0.6.2",string url="https://github.com/nexaridev/veyra/releases/download/v0.6.2/fixture.zip"){
   string hash;using(var sha=SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(zip)).Replace("-","").ToLowerInvariant();string payload=Json.Serialize(new{schema=1,version=version,windows=new{url=url,sha256=hash,size=zip.Length}});byte[] bytes=Encoding.UTF8.GetBytes(payload);var signer=new Ed25519Signer();signer.Init(true,key);signer.BlockUpdate(bytes,0,bytes.Length);return Json.Serialize(new{payload=payload,signature=Convert.ToBase64String(signer.GenerateSignature())});
  }
  static Network Net(FakeHttp http){return new Network(http,text=>Manifest.VerifyWithKey(text,pub));}
  static async Task Reject(Func<Task> operation,string name){bool rejected=false;try{await operation().ConfigureAwait(false);}catch(Exception){rejected=true;}Check(rejected,name);}
  static async Task Run(){
   byte[] seed=new byte[32];using(var rng=RandomNumberGenerator.Create())rng.GetBytes(seed);key=new Ed25519PrivateKeyParameters(seed,0);pub=key.GeneratePublicKey().GetEncoded();byte[] zip=Bundle();string envelope=Envelope(zip);
   Check(Manifest.VerifyWithKey(envelope,pub).Version=="0.6.2","Valid signature rejected");await Reject(()=>Task.Run(()=>Manifest.Verify(envelope)),"Foreign signing key accepted");
   await Reject(()=>Task.Run(()=>Manifest.VerifyWithKey(envelope.Replace("0.6.2","0.6.3"),pub)),"Tampered signature accepted");await Reject(()=>Task.Run(()=>Manifest.VerifyWithKey(Envelope(zip,"0.6.2","https://evil.invalid/payload.zip"),pub)),"Foreign artifact accepted");
   var layout=new Layout(Path.Combine(root,"installed"));var integration=new TestIntegration();var progress=new TestProgress();string own=Assembly.GetExecutingAssembly().Location;
   using(var net=Net(new FakeHttp{Zip=zip,Envelope=envelope}))await new Installer(layout,integration,own).Install(net,new Options{Desktop=false,StartMenu=false},progress,CancellationToken.None).ConfigureAwait(false);
   Check(File.ReadAllText(layout.Exe)=="verified","Verified files not installed");Check(layout.Owns()&&File.Exists(layout.SetupExe),"Installer ownership/manager missing");
   byte[] update=Bundle("replacement");var failed=new TestIntegration{Fail=true};using(var net=Net(new FakeHttp{Zip=update,Envelope=Envelope(update,"0.6.3")}))await Reject(()=>new Installer(layout,failed,own).Install(net,new Options(),progress,CancellationToken.None),"Integration failure accepted");Check(failed.Restored&&File.ReadAllText(layout.Exe)=="verified","Previous app not restored");Check(File.ReadAllLines(layout.Marker)[1]=="0.6.2","Previous version marker not restored");
   byte[] bad=(byte[])zip.Clone();bad[bad.Length/2]^=1;var badLayout=new Layout(Path.Combine(root,"corrupt"));using(var net=Net(new FakeHttp{Zip=bad,Envelope=envelope}))await Reject(()=>new Installer(badLayout,new TestIntegration(),own).Install(net,new Options(),progress,CancellationToken.None),"Corrupt archive accepted");Check(!File.Exists(badLayout.Exe),"Corrupt payload installed");
   foreach(string name in new[]{"Veyra-win32-x64/../../escape.exe","Veyra-win32-x64/a.txt:stream","Veyra-win32-x64/CON","Veyra-win32-x64/alias.","Veyra-win32-x64/VEYRA.EXE"}){string archivePath=Path.Combine(root,Guid.NewGuid()+".zip"),stage=Path.Combine(root,Guid.NewGuid().ToString());Directory.CreateDirectory(stage);File.WriteAllBytes(archivePath,Bundle("safe",name));await Reject(()=>Task.Run(()=>Archive.Extract(archivePath,stage,progress,CancellationToken.None)),"Unsafe ZIP path accepted: "+name);}Check(!File.Exists(Path.Combine(root,"escape.exe")),"ZIP escaped staging");
   var redirect=new FakeHttp{Redirect=new Uri("http://evil.invalid/zip")};using(var net=Net(redirect))await Reject(()=>net.Latest(CancellationToken.None),"Insecure redirect accepted");Check(redirect.Calls==1,"Contacted redirect host before validation");
   var cancelLayout=new Layout(Path.Combine(root,"cancelled"));using(var cts=new CancellationTokenSource())using(var net=Net(new FakeHttp{Zip=zip,Envelope=envelope})){var cancelProgress=new TestProgress();cancelProgress.Changed=value=>{if(value.Text=="Распаковка файлов")cts.Cancel();};await Reject(()=>new Installer(cancelLayout,new TestIntegration(),own).Install(net,new Options(),cancelProgress,cts.Token),"Cancellation ignored");}Check(!File.Exists(cancelLayout.Exe)&&Directory.GetDirectories(cancelLayout.Root,".stage-*").Length==0,"Cancelled installation left staged files");
   string sentinel=Path.Combine(root,"profile-sentinel");File.WriteAllText(sentinel,"keep");new Installer(layout,integration,own).Uninstall();Check(!Directory.Exists(layout.App)&&integration.Removed,"Uninstall did not remove app/integration");Check(File.ReadAllText(sentinel)=="keep","Uninstall touched unrelated data");
   string shortcut=Path.Combine(root,"Veyra-test.lnk");Integration.MakeShortcut(shortcut,layout);Check(File.Exists(shortcut)&&new FileInfo(shortcut).Length>0,"Actual Windows shortcut creation failed");
   Console.WriteLine("PASS: "+count+" installer checks — signatures, redirects, SHA-256, ZIP paths, transaction rollback, cancellation, uninstall scope and real shortcut creation");
  }
  [STAThread]public static void Main(string[] args){try{
   AppDomain.CurrentDomain.AssemblyResolve+=delegate(object sender,ResolveEventArgs e){if(new AssemblyName(e.Name).Name!="BouncyCastle.Cryptography")return null;using(var input=Assembly.GetExecutingAssembly().GetManifestResourceStream("bc.gz"))using(var gzip=new GZipStream(input,CompressionMode.Decompress))using(var memory=new MemoryStream()){gzip.CopyTo(memory);return Assembly.Load(memory.ToArray());}};
   root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);Run().GetAwaiter().GetResult();Application.EnableVisualStyles();using(var form=new SetupForm(false))using(var bitmap=new Bitmap(form.Width,form.Height)){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-10000,-10000);form.ShowInTaskbar=false;form.Show();Application.DoEvents();form.DrawToBitmap(bitmap,new Rectangle(0,0,bitmap.Width,bitmap.Height));bitmap.Save(Path.Combine(root,"installer.png"));}Console.WriteLine("PASS: installer interface rendered to installer.png");
  }catch(Exception error){Console.Error.WriteLine(error.ToString());Environment.ExitCode=1;}}
 }
}
